// Yield to the browser between chunks so clicks and paints can happen.
const yieldToMain = (): Promise<void> =>
  // scheduler.yield() is not in every browser yet: feature-detect.
  (globalThis as any).scheduler?.yield
    ? (globalThis as any).scheduler.yield()
    : new Promise((resolve) => setTimeout(resolve, 0));

export async function processAll<T>(
  items: T[],
  work: (item: T) => void,
  budgetMs = 40,
): Promise<void> {
  let deadline = performance.now() + budgetMs;
  for (const item of items) {
    work(item);
    if (performance.now() > deadline) {
      await yieldToMain(); // a real task boundary, not just a microtask
      deadline = performance.now() + budgetMs;
    }
  }
}

