// Run fn over items, at most `limit` at a time. Never rejects: returns each outcome.
export async function mapLimit<T, R>(
  items: T[],
  limit: number,
  fn: (item: T, signal: AbortSignal) => Promise<R>,
): Promise<PromiseSettledResult<R>[]> {
  const results: PromiseSettledResult<R>[] = new Array(items.length);
  let next = 0;

  async function worker() {
    while (next < items.length) {
      const i = next++; // safe: JS is single-threaded between awaits
      try {
        // Each call gets its own 5s timeout.
        const value = await fn(items[i], AbortSignal.timeout(5000));
        results[i] = { status: 'fulfilled', value };
      } catch (reason) {
        results[i] = { status: 'rejected', reason };
      }
    }
  }

  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

