import { useEffect, useRef, useState } from 'react';

export function useLatest<T>(value: T) {
  const ref = useRef(value);
  // Update after render so the ref never shows uncommitted values.
  useEffect(() => {
    ref.current = value;
  });
  return ref;
}

export function Ticker({ onTick }: { onTick: (n: number) => void }) {
  const [count, setCount] = useState(0);
  const onTickRef = useLatest(onTick);

  useEffect(() => {
    const id = setInterval(() => {
      setCount((c) => c + 1);          // functional update: no stale count
      onTickRef.current(Date.now());   // latest prop, interval not restarted
    }, 1000);
    return () => clearInterval(id);    // cleanup: no leaked interval
  }, [onTickRef]);

  return <span>{count}</span>;
}

