import { LRUCache } from 'lru-cache';

// Before: const cache = new Map<string, Product>(); // grows forever

const cache = new LRUCache<string, Product>({
  max: 5_000,            // at most 5k entries
  ttl: 5 * 60_000,       // entries expire after 5 minutes
  updateAgeOnGet: false,
});

export async function getProduct(id: string): Promise<Product> {
  const hit = cache.get(id);
  if (hit) return hit;
  const product = await db.product.findUniqueOrThrow({ where: { id } });
  cache.set(id, product);
  return product;
}

// Expose numbers so a leak is visible on a dashboard.
setInterval(() => {
  const { heapUsed, rss } = process.memoryUsage();
  metrics.gauge('cache_entries', cache.size);
  metrics.gauge('heap_used_bytes', heapUsed);
  metrics.gauge('rss_bytes', rss);
}, 15_000).unref();

