type Point = { x: number; y: number; label: string | undefined };

// Bad: properties added conditionally and in different orders.
// Each variant is a different hidden class, so the hot function goes megamorphic.
function parseBad(row: string[]) {
  const p: any = {};
  if (row[2]) p.label = row[2];
  p.y = Number(row[1]);
  p.x = Number(row[0]);
  return p;
}

// Good: one literal, same keys, same order, every time.
function parseGood(row: string[]): Point {
  return {
    x: Number(row[0]),
    y: Number(row[1]),
    label: row[2] || undefined,
  };
}

function sumX(points: Point[]) {
  let s = 0;
  for (const p of points) s += p.x; // monomorphic access: fast
  return s;
}

