type Payment =
  | { status: 'pending'; id: string }
  | { status: 'paid'; id: string; paidAt: Date }
  | { status: 'failed'; id: string; reason: string };

function assertNever(x: never): never {
  throw new Error(`Unhandled case: ${JSON.stringify(x)}`);
}

export function label(p: Payment): string {
  switch (p.status) {
    case 'pending':
      return 'Waiting for bank';
    case 'paid':
      return `Paid on ${p.paidAt.toLocaleDateString()}`; // paidAt exists here
    case 'failed':
      return `Failed: ${p.reason}`;
    default:
      return assertNever(p); // compile error if a status is added and not handled
  }
}

