const routes = {
  user: '/users/:userId',
  order: '/users/:userId/orders/:orderId',
} as const satisfies Record<string, string>;

// '/users/:userId/orders/:orderId' -> 'userId' | 'orderId'
type Params<P extends string> =
  P extends `${string}:${infer Name}/${infer Rest}`
    ? Name | Params<`/${Rest}`>
    : P extends `${string}:${infer Name}`
      ? Name
      : never;

export function href<K extends keyof typeof routes>(
  name: K,
  params: Record<Params<(typeof routes)[K]>, string>,
): string {
  return routes[name].replace(/:(\w+)/g, (_, key: string) =>
    encodeURIComponent((params as Record<string, string>)[key]),
  );
}

