import { z } from 'zod';

// 1. Env: fail fast at startup, not at the first request.
const Env = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']),
  DATABASE_URL: z.url(),
  PORT: z.coerce.number().int().default(3000),
});
export const env = Env.parse(process.env);

// 2. Request body: allow-list of editable fields, unknown keys rejected.
const UpdateProfile = z.strictObject({
  name: z.string().trim().min(1).max(80),
  bio: z.string().max(500).optional(),
});
type UpdateProfile = z.infer<typeof UpdateProfile>;

app.patch('/me', async (req, res) => {
  const result = UpdateProfile.safeParse(req.body);
  if (!result.success) {
    return res.status(422).json(z.flattenError(result.error));
  }
  const data: UpdateProfile = result.data; // typed and clean
  await db.user.update({ where: { id: req.user.id }, data });
  res.status(204).end();
});

